--
-- Estructura de tabla para la tabla `inventario_productos`
--

CREATE TABLE `inventario_productos` (
  `id` int(11) NOT NULL,
  `nombre` varchar(255) NOT NULL,
  `categoria` varchar(150) DEFAULT NULL,
  `marca` varchar(150) DEFAULT NULL,
  `stock_actual` int(11) DEFAULT 0,
  `stock_inicial` int(11) DEFAULT 0,
  `stock_minimo` int(11) DEFAULT 0,
  `estado` varchar(50) DEFAULT NULL,
  `precio_caja` decimal(10,2) DEFAULT NULL,
  `costo_compra` decimal(10,3) DEFAULT NULL,
  `precio_unitario` decimal(10,2) DEFAULT NULL,
  `precio_blister` decimal(10,2) DEFAULT NULL,
  `precio_caja_venta` decimal(10,2) DEFAULT NULL,
  `unidades_blister` varchar(50) DEFAULT NULL,
  `blisters_caja` varchar(50) DEFAULT NULL,
  `vencimiento` varchar(50) DEFAULT NULL,
